import { z } from "zod";
import type { BudgetPlan } from "@/lib/budget";

export const DEFAULT_DAYS = 3;
export const MIN_DAYS = 2;
export const MAX_DAYS = 7;

/** Duración elegida: entero de 2 a 7. */
export const DaysSchema = z.number().int().min(MIN_DAYS).max(MAX_DAYS);

export const ItineraryDaySchema = z.object({
  day: z.number().int().positive(),
  title: z.string().trim().min(1),
  activities: z.array(z.string().trim().min(1)).min(1),
  costUsd: z.number().int().min(0),
});

/** Esquema del plan con exactamente `days` días; totalUsd lo calcula applyBudget. */
export function itineraryResponseSchema(days: number) {
  return z.object({
    intro: z.string().trim().min(1),
    days: z.array(ItineraryDaySchema).length(days),
    hiddenGem: z.object({
      title: z.string().trim().min(1),
      description: z.string().trim().min(1),
    }),
    localFood: z.object({
      dish: z.string().trim().min(1),
      description: z.string().trim().min(1),
    }),
    totalUsd: z.number().int().min(0),
  });
}

/** Un solo tipo de plan: el de budget.ts. */
export type TravelPlan = BudgetPlan;
EOF
